SELECT chat_message_id, member_id, message_role,
       content_ko, content_local, language_code, created_at
FROM chat_message
WHERE member_id = #{memberId}
ORDER BY chat_message_id DESC
LIMIT #{limit}

SELECT chat_message_id, member_id, message_role,
content_ko, content_local, language_code, card_type, card_payload, created_at
FROM chat_message
WHERE member_id = #{memberId}

    AND chat_message_id < #{before}

ORDER BY chat_message_id DESC
LIMIT #{size}
